-- GenDB engine variant Q18-wrapped_tables: template q18.sql, kind wrapped_tables (generated by generate.py; frozen)
SELECT
  c_name,
  c_custkey,
  o_orderkey,
  o_orderdate,
  o_totalprice,
  SUM(l_quantity) AS sum_qty
FROM (
  SELECT
    *
  FROM customer
) AS customer, (
  SELECT
    *
  FROM orders
) AS orders, (
  SELECT
    *
  FROM lineitem
) AS lineitem
WHERE
  o_orderkey IN (
    SELECT
      l_orderkey
    FROM (
      SELECT
        *
      FROM lineitem
    ) AS lineitem
    GROUP BY
      l_orderkey
    HAVING
      SUM(l_quantity) > $1
  )
  AND c_custkey = o_custkey
  AND o_orderkey = l_orderkey
GROUP BY
  c_name,
  c_custkey,
  o_orderkey,
  o_orderdate,
  o_totalprice
ORDER BY
  o_totalprice DESC,
  o_orderdate
LIMIT 100
